import * as T from './vendor/three.module.js';
import {materials,part,animateUnit} from './models-3d.js';
import {designUnit} from './models-design.js';

export class CharacterView{
 constructor(canvas,unit){this.canvas=canvas;this.unit={...unit};this.pose='idle';this.yaw=.3;this.pitch=.12;this.zoom=1;this.disposed=false;this.gl=new T.WebGLRenderer({canvas,antialias:true,alpha:true});this.gl.setPixelRatio(Math.min(devicePixelRatio||1,2));this.gl.outputColorSpace=T.SRGBColorSpace;this.gl.toneMapping=T.ACESFilmicToneMapping;this.gl.toneMappingExposure=1;this.gl.shadowMap.enabled=true;this.gl.shadowMap.type=T.PCFSoftShadowMap;this.scene=new T.Scene();this.M=materials();this.camera=new T.OrthographicCamera(-1,1,1,-1,.1,40);this.model=designUnit(unit.npcRole||unit.type,unit.technology||0,Math.max(1,unit.training||1),this.M,false,unit.species);this.scene.add(this.model);const bounds=new T.Box3().setFromObject(this.model);this.height=Math.max(1.5,bounds.max.y+.12);this.center=new T.Vector3(0,this.height*.5,0);this.scene.add(new T.HemisphereLight('#e6edf0','#6c6251',1.35));const key=new T.DirectionalLight('#ffdeb0',3.2);key.position.set(-3,5,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);Object.assign(key.shadow.camera,{left:-2,right:2,top:3,bottom:-2,near:.1,far:15});key.shadow.normalBias=.02;this.scene.add(key);const rim=new T.DirectionalLight('#a4d8e7',1.7);rim.position.set(2,3,-3);this.scene.add(rim);const floor=part(this.scene,'ground',this.M.contact,0,-.012,0,3,1,3);floor.castShadow=false;floor.receiveShadow=true;
  this.abort=new AbortController();const options={signal:this.abort.signal};let pointer=null;canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointer={x:e.clientX,y:e.clientY};},options);canvas.addEventListener('pointermove',e=>{if(!pointer)return;this.yaw+=(e.clientX-pointer.x)*.012;this.pitch=Math.max(-.05,Math.min(.6,this.pitch+(e.clientY-pointer.y)*.006));pointer={x:e.clientX,y:e.clientY};},options);for(const type of['pointerup','pointercancel'])canvas.addEventListener(type,()=>pointer=null,options);canvas.addEventListener('wheel',e=>{e.preventDefault();this.zoom=Math.max(.7,Math.min(1.8,this.zoom-e.deltaY*.001));},{...options,passive:false});this.resize=new ResizeObserver(()=>this.fit());this.resize.observe(canvas);this.fit();this.last=0;this.loop=t=>{if(this.disposed)return;if(!document.hidden&&t-this.last>32){this.last=t;this.model.rotation.y=this.yaw;const moving=this.pose==='walk',working=this.pose==='work';this.unit.cooldown=this.pose==='attack'?1.3-(t/1000%1.3):0;animateUnit(this.model,this.unit,t/1000,moving,working,false);this.fitCamera();this.gl.render(this.scene,this.camera);canvas.dataset.frames=String((Number(canvas.dataset.frames)||0)+1);canvas.dataset.pose=this.pose;canvas.dataset.yaw=this.yaw.toFixed(3);}this.raf=requestAnimationFrame(this.loop);};this.raf=requestAnimationFrame(this.loop);canvas.dataset.characterRevision=this.model.userData.characterRevision||12;
 }
 fit(){if(this.disposed)return;const r=this.canvas.getBoundingClientRect();this.w=Math.max(1,r.width);this.h=Math.max(1,r.height);this.gl.setSize(this.w,this.h,false);this.fitCamera();}
 fitCamera(){const half=this.height*.62/this.zoom,aspect=this.w/this.h;Object.assign(this.camera,{left:-half*aspect,right:half*aspect,top:half,bottom:-half});this.camera.position.set(0,this.center.y+1+this.pitch*3,5);this.camera.lookAt(this.center);this.camera.updateProjectionMatrix();}
 setPose(pose){if(['idle','walk','work','attack'].includes(pose))this.pose=pose;}
 dispose(){if(this.disposed)return;this.disposed=true;cancelAnimationFrame(this.raf);this.resize.disconnect();this.abort.abort();const textures=new Set();for(const m of Object.values(this.M)){if(m.map&&!m.map.userData.shared)textures.add(m.map);if(m.normalMap&&!m.normalMap.userData.shared)textures.add(m.normalMap);m.dispose();}textures.forEach(t=>t.dispose());this.gl.dispose();this.gl.forceContextLoss();this.scene.clear();}
}
